      function show(i) {
        tickerIdx = (i + items.length) % items.length;
        var t = $("#tickerTitle");
        if (t) { t.textContent = items[tickerIdx].title; t.onclick = function () { openArticle(items[tickerIdx].id); }; }
      }
      show(0);
      var prev = $("#tickerPrev"), next = $("#tickerNext");
      if (prev) prev.onclick = function () { show(tickerIdx - 1); restart(); };
